### FUNCION: handleCellInput
```js
function handleCellInput(e) {
    const cellElement = e.currentTarget;
    const key = getCellKey(cellElement.dataset.col, cellElement.dataset.row);
    let newValue = cellElement.innerText.trim();

    // 1. Update the raw input value in the state
    spreadsheetData[key].rawInput = newValue;
    saveState();

    // 2. Check if the new value is a formula or plain text/number
    if (newValue && newValue.startsWith('=')) {
        // If it's a formula, we don't update the displayed value yet, just the raw input.
        updateCellDOM(key, spreadsheetData[key]);
        // Trigger recalculation immediately because the formula itself changed.
        triggerRecalculation(key);
    } else {
        // If it's plain text/number, calculate and set the value.
        const calculatedValue = calculateFormula(newValue);
        spreadsheetData[key].value = calculatedValue;
        spreadsheetData[key].rawInput = newValue;

        updateCellDOM(key, spreadsheetData[key]);
        // Crucial fix: Trigger recalculation for all dependent cells because a non-formula cell changed.
        triggerRecalculation(key);
    }

    // Clean up the active edit state
    cellElement.classList.remove('active-edit');
    document.removeEventListener('blur', handleCellInput); // Assuming this was added during focus/input handling
}
