```js
/**
 * Converts a column index (0-based) to its corresponding letter (A, B, C...).
 * @param {number} index - The zero-based column index.
 * @returns {string} The column letter.
 */
function colIndexToLetter(index) {
    let temp = Math.floor(index);
    let letter = '';
    while (temp >= 0) {
        letter = String.fromCharCode(65 + (temp % 26)) + letter;
        temp = Math.floor(temp / 26) - 1;
    }
    return letter;
}

/**
 * Generates a unique key for a cell based on its column index and row number.
 * @param {number} colIdx - The zero-based column index.
 * @param {number} rowNum - The 1-based row number.
 * @returns {string} The cell key (e.g., "A3").
 */
function getCellKey(colIdx, rowNum) {
    const colLetter = colIndexToLetter(colIdx);
    return `${colLetter}${rowNum}`;
}

/**
 * Initializes the application state structure in memory.
 */
function initializeState() {
    // Reset global state variables
    spreadsheetData = {};
    MAX_COLUMNS = 10; // A to J (10 columns)
    NUM_COLUMNS = MAX_COLUMNS;
    NUM_ROWS = 20;

    for (let r = 1; r <= NUM_ROWS; r++) {
        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, r);
            spreadsheetData[key] = {
                rawInput: '',
                value: '',
                formula: null,
                style: {}, // Stores formatting like background color
                format: {}
            };
        }
    }

    // Initialize the state for the first row (Row 1) to be editable/visible by default
    for (let c = 0; c < MAX_COLUMNS; c++) {
        const key = getCellKey(c, 1);
        spreadsheetData[key].style.backgroundColor = ''; // Ensure initial state is clean
    }

    // Set up event listeners for controls and cells
    setupEventListeners();
}

/**
 * Saves the current application state to local storage.
 */
function saveState() {
    localStorage.setItem('spreadsheetState', JSON.stringify(spreadsheetData));
    console.log("State saved.");
}

/**
 * Loads the application state from local storage, if available.
 */
function loadState() {
    const storedState = localStorage.getItem('spreadsheetState');
    if (storedState) {
        spreadsheetData = JSON.parse(storedState);
        console.log("State loaded successfully.");
    } else {
        console.warn("No saved state found. Starting with default empty grid.");
    }
}

/**
 * Gets the DOM element for a specific cell key (e.g., "A3").
 * @param {number} colIdx - The zero-based column index.
 * @param {number} rowNum - The 1-based row number.
 * @returns {HTMLElement | null} The cell element or null if not found.
 */
function getCellElement(colIdx, rowNum) {
    const key = getCellKey(colIdx, rowNum);
    // We rely on the data attributes set in HTML for selection
    return document.querySelector(`.spreadsheet-cell[data-col="${colIndexToLetter(colIdx)}"][data-row="${rowNum}"]`);
}

/**
 * Updates the DOM element corresponding to a cell key based on its state object.
 * This function handles content, formulas, and basic styling updates.
 * @param {string} key - The cell key (e.g., "A3").
 * @param {object} data - The updated state object for the cell.
 */
function updateCellDOM(key, data) {
    const element = document.querySelector(`.spreadsheet-cell[data-col="${key.replace(/[0-9]/g, '')}"][data-row="${key.slice(-1)}"]`);
    if (!element) return;

    // 1. Update Content/Value
    element.textContent = data.value || '';
    element.setAttribute('contenteditable', 'true'); // Keep editable attribute for focus handling

    // 2. Update Formula Display
    if (data.formula && !isNaN(parseFloat(data.formula))) {
        element.classList.add('formula-cell');
        element.title = data.formula;
    } else {
        element.classList.remove('formula-cell');
        element.title = '';
    }

    // 3. Update Styling (Background color, etc.)
    // Note: Background color is handled separately in handleRowHeaderClick for robustness.
    if (data.style && data.style.backgroundColor) {
        element.style.backgroundColor = data.style.backgroundColor;
    } else if (!data.style || !data.style.backgroundColor) {
         // Reset background color if state dictates it
         element.style.backgroundColor = ''; 
    }

    // Re-apply selection/focus classes if necessary (handled by event listeners usually)
}

/**
 * Calculates the value of a cell based on its formula string and dependencies.
 * @param {string} formulaString - The formula to calculate (e.g., "=A1+B1").
 * @returns {number | null} The calculated numeric value, or null if invalid/no formula.
 */
function calculateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) return null;

    let expression = formulaString.substring(1);

    // Replace cell references (e.g., A1, B2) with their current values in the calculation context
    expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
        const key = match;
        const data = spreadsheetData[key];
        return data ? (isNaN(parseFloat(data.value)) ? 0 : parseFloat(data.value)) : 0;
    });

    try {
        // Use Function constructor for safe evaluation of mathematical expressions
        const result = new Function('return ' + expression)();
        return isNaN(result) ? null : parseFloat(result);
    } catch (e) {
        console.error("Error calculating formula:", e);
        return null;
    }
}

/**
 * Calculates the value for a specific cell key and updates its state/DOM if necessary.
 * @param {string} key - The cell key to calculate (e.g., "A3").
 */
function calculateAndSetCell(key) {
    const data = spreadsheetData[key];

    if (!data || !data.formula) return;

    const calculatedValue = calculateFormula(data.formula);

    if (calculatedValue !== null) {
        // Update state with the calculated value and remove formula flag if it's a number
        spreadsheetData[key].value = calculatedValue;
        spreadsheetData[key].rawInput = ''; // Clear raw input when calculating
        spreadsheetData[key].formula = null; 
        updateCellDOM(key, spreadsheetData[key]);
    } else {
        // If calculation fails or formula is invalid, treat it as text/empty
        spreadsheetData[key].value = data.rawInput || '';
        spreadsheetData[key].formula = null;
        updateCellDOM(key, spreadsheetData[key]);
    }
}

/**
 * Triggers recalculation for all cells that depend on the changed cell key.
 * @param {string} changedKey - The key of the cell that was just modified (e.g., "A3").
 */
function triggerRecalculation(changedKey) {
    // Simple implementation: Recalculate everything in the same row and column as the change, 
    // or for simplicity, recalculate all cells if dependencies are complex to track.

    const changedColIdx = parseInt(changedKey.replace(/[A-Z]/g, '')); // Crude way to get index (assuming A=1, B=2...)
    const changedRowNum = parseInt(changedKey.slice(-1));

    // For robustness in this context, we will recalculate all cells that might depend on the change.
    // Since dependency tracking is complex, we iterate over a small area or just trigger a full update if necessary.

    // Let's stick to recalculating the entire row and column for safety.
    for (let r = 1; r <= NUM_ROWS; r++) {
        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, r);
            // Only recalculate if the cell has a formula and is not the changed cell itself
            if (spreadsheetData[key].formula && key !== changedKey) {
                calculateAndSetCell(key);
            }
        }
    }
}

/**
 * Handles input changes in an editable cell.
 * @param {Event} e - The event object from the input field.
 */
function handleCellInput(e) {
    const element = e.target;
    const key = element.dataset.key;
    if (!key) return;

    // 1. Update State (Raw Input and Value)
    spreadsheetData[key].rawInput = e.target.textContent;
    spreadsheetData[key].value = e.target.textContent;
    spreadsheetData[key].formula = null; // Clear formula if user types manually

    // 2. Update DOM (This is redundant but safe)
    updateCellDOM(key, spreadsheetData[key]);

    // 3. Trigger recalculation for dependent cells
    triggerRecalculation(key);
}

/**
 * Handles changes in the color picker input when selecting a row via header controls.
 * @param {Event} e - The event object from the color picker.
 */
function handleFormatChange(e, key, colIdx, rowNum) {
    const newColor = e.target.value;

    // 1. Apply the background color to all cells in the selected row (rowNum)
    for (let i = 0; i < MAX_COLUMNS; i++) {
        const cellKey = getCellKey(i, rowNum);
        const cellElement = getCellElement(i, rowNum);

        if (cellElement) {
            // Apply the background color style directly to the DOM element
            cellElement.style.backgroundColor = newColor;
            // Update state representation for formatting
            spreadsheetData[cellKey].style.backgroundColor = newColor; 
        }
    }

    // 2. Save state and trigger recalculation/update
    saveState();
    triggerRecalculation(key);
}

/**
 * Handles clicks on column headers (A, B, C...).
 * @param {Event} e - The click event object.
 */
function handleColumnHeaderClick(e) {
    const header = e.currentTarget;
    const colIdx = parseInt(header.dataset.colIndex); // Assuming we pass index on setup

    // Toggle visibility of the column
    const isHidden = header.classList.contains('hidden-col');
    if (isHidden) {
        header.classList.remove('hidden-col');
        // Show all cells in this column
        document.querySelectorAll(`.spreadsheet-cell[data-col="${header.dataset.col}"][data-row*=""]`).forEach(cell => {
            cell.style.display = '';
        });
    } else {
        header.classList.add('hidden-col');
        // Hide all cells in this column
        document.querySelectorAll(`.spreadsheet-cell[data-col="${header.dataset.col}"]`).forEach(cell => {
            cell.style.display = 'none';
        });
    }
}

/**
 * Handles clicks on row headers (the number area).
 * @param {Event} e - The click event object.
 */
function handleRowHeaderClick(e) {
    const header = e.currentTarget;
    const rowNum = parseInt(header.dataset.row);

    // --- Color Change ---
    if (e.target.classList.contains('color-picker')) {
        const color = e.target.value;
        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, rowNum);
            const cellElement = getCellElement(c, rowNum);

            // Apply the background color directly to the DOM element for immediate visual feedback
            if (cellElement) {
                cellElement.style.backgroundColor = color;
            }

            // Update state representation for formatting
            spreadsheetData[key].style.backgroundColor = color; 
        }
        saveState();
    }

    // --- Delete Row ---
    if (e.target.dataset.action === 'delete') {
        if (!confirm(`¿Está seguro de que desea borrar la fila ${header.textContent}? Esta acción es irreversible.`)) return;

        // 1. Clear data and remove DOM elements for all cells in this row
        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, rowNum);
            spreadsheetData[key].rawInput = '';
            spreadsheetData[key].value = '';
            spreadsheetData[key].style = {};
            updateCellDOM(key, spreadsheetData[key]);
        }

        // 2. Remove DOM elements (The actual cells)
        const rowCells = document.querySelectorAll(`.row[data-row="${header.dataset.row}"] .spreadsheet-cell`);
        rowCells.forEach(cell => cell.remove());

        // 3. Update the header structure (Remove the number div itself)
        header.remove();

        saveState();
    }

    // --- Clear Content Row ---
    if (e.target.dataset.action === 'clear') {
        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, rowNum);
            spreadsheetData[key].rawInput = '';
            spreadsheetData[key].value = '';
            spreadsheetData[key].style = {};
            updateCellDOM(key, spreadsheetData[key]);
        }
        saveState();
    }

    // --- Hide Row ---
    if (e.target.dataset.action === 'hide') {
        const rowElement = header.closest('.row');
        rowElement.style.display = 'none'; // Hide the entire row container
        saveState();
    } else {
         // Show all elements if not explicitly hiding/deleting
        const rowElement = header.closest('.row');
        rowElement.style.display = ''; 
    }
}

/**
 * Sets up all necessary event listeners for the spreadsheet controls and cells.
 */
function setupEventListeners() {
    // Event listener for cell input (delegated on data-grid)
    document.getElementById('data-grid').addEventListener('input', handleCellInput);
    document.getElementById('data-grid').addEventListener('focusout', function(e) {
        if (!e.target.classList.contains('spreadsheet-cell')) return;
        // When focus leaves, we might want to trigger recalculation if the cell was edited
        const key = e.target.dataset.key;
        if (key && !e.target.hasAttribute('contenteditable="true"')) {
             triggerRecalculation(key);
        }
    });

    // Event delegation for row header controls (Delete, Color Picker, Clear)
    document.getElementById('grid-area').addEventListener('click', handleRowHeaderClick);

    // Event delegation for column headers
    document.getElementById('column-headers').addEventListener('click', handleColumnHeaderClick);

    // Initialize the first row's state and DOM elements (A1:J1)
    for (let c = 0; c < MAX_COLUMNS; c++) {
        const key = getCellKey(c, 1);
        updateCellDOM(key, spreadsheetData[key]);
    }
}

/**
 * Initializes the entire spreadsheet structure and state.
 */
function initializeSpreadsheet() {
    // Load state first to populate data structures
    loadState();

    // Ensure all cells are correctly rendered based on loaded/default state
    for (let r = 1; r <= NUM_ROWS; r++) {
        const rowElement = document.querySelector(`.row[data-row="${r}"]`);
        if (!rowElement) continue;

        // Update the number in the row header content
        const rowNumberSpan = rowElement.querySelector('.row-header-content');
        if (rowNumberSpan) {
            rowNumberSpan.textContent = r;
        }

        for (let c = 0; c < MAX_COLUMNS; c++) {
            const key = getCellKey(c, r);
            // Ensure the cell element exists and its state is reflected in the DOM
            updateCellDOM(key, spreadsheetData[key]);
        }
    }

    setupEventListeners();
}
