function loadState() {
    const savedState = localStorage.getItem(STORAGE_KEY);
    if (savedState) {
        try {
            const loadedData = JSON.parse(savedState);
            // Merge loaded data into the initialized state, ensuring all keys exist
            spreadsheetData = { ...spreadsheetData, ...loadedData };

            // After loading state, we must update the DOM elements to reflect the saved values.
            for (const key in spreadsheetData) {
                if (spreadsheetData[key] !== undefined) {
                    updateCellDOM(key, spreadsheetData[key]);
                }
            }
        } catch (e) {
            console.error("Error loading state:", e);
            // If corrupted, start fresh
            initializeState();
        }
    } else {
        initializeState();
    }
}
