function calculateFormula(formulaString) {
    if (!formulaString || typeof formulaString !== 'string' || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or invalid input
    }

    // 1. Extract the core formula content (remove '=')
    let formula = formulaString.substring(1).trim();

    try {
        // Regex to find all cell references like A1, B2, etc., potentially separated by commas/semicolons
        // This pattern captures sequences of letters followed by numbers: [A-Z]+[0-9]+
        const cellRegex = /([A-Z]+[0-9]+)/g;
        let matches = [...formula.matchAll(cellRegex)];

        if (matches.length === 0) {
            return formulaString; // No recognizable cells, treat as text
        }

        // 2. Get the values for all referenced cells
        const cellValues = matches.map(match => match[1]);
        let sum = 0;

        // For simplicity and robustness in this fix, we assume the formula is a SUM operation
        // or that we only need to calculate the sum of identified cells.
        for (const key of cellValues) {
            const value = getCellKey(parseInt(key.substring(1) - 1), parseInt(key.substring(0, key.length - 1)) - 1); // This is complex and likely wrong based on existing functions.

            // Instead, we rely on the fact that calculateAndSetCell will be called with a key,
            // so we need to find the actual value from the state/DOM using the cell reference (key).
