            }
        }

        // Since the test case is specifically SUMA(A1;B1), let's simplify the calculation logic to handle multiple arguments passed to SUMA.
        // We assume all identified cells must be summed up if they are numeric.
        let totalSum = 0;
        for (const key of cellValues) {
            const coordinates = getCellCoordinates(key); // Assuming this function correctly maps A1 -> 'A_1' format used by the app state

            if (coordinates && spreadsheetData[coordinates] !== undefined) {
                let value = parseFloat(spreadsheetData[coordinates]);
                if (!isNaN(value)) {
                    totalSum += value;
                }
            }
        }


